      marks: 2,
      neg: 0.66,
      type: "MCQ",
      text: `<p> In a multiple choice question paper having 30 questions, the marking scheme is as under:<br/> +5 marks for each correct question;<br/> +1 mark for each unanswered question;<br/> No score for wrong response.<br/> A group of 4 students named Arun, Bishal, Chetan and Dhawal gave the following statements:<br/> <strong>Arun:</strong> My score is 141<br/> <strong>Bishal:</strong> I have scored 144<br/> <strong>Chetan:</strong> My score is 147<br/> <strong>Dhawal:</strong> I scored 139.<br/>Only one of the students has got a valid score. What is the name of that student? </p>`,
      image: "",
