      image: "",
      options: [],
      answer: [76659, 76659],
      solution: `<p> Since digit ‘6 ’is coming twice in each of the numbers formed, we can say that<br/> ‘4 ’comes in unit ’s place 3 times<br/> ‘6 ’comes in unit ’s place 6 times<br/> ‘7 ’comes in unit ’s place 3 times leading to sum of unit digit of all possible numbers as<br/> (3 ×4) + (6 ×6) + (3 ×7) = 69.<br/> For digits in 10 ’s place, in hundred ’s place as well as thousand ’s place also, the sum of respective digit of all the possible numbers will be 69.<br/> The sum of all possible numbers will be<br/>(1 ×69) + (10 ×69) + (100 ×69) + (1000 ×69) = 1111 ×69 = 76659 </p>`,
