      text: `<p>In this question, a group of numbers/symbols is coded using letter codes as per the codes given below and the conditions which follow. The correct combination of codes following the conditions is your answer. If none of the conditions follow, then codes for the respective Number/Symbol are to be followed directly as given in the table.</p> <p> <img src="images/quiz/ee_swt_ga/q33_1.png" style="max-width: 100%;"/> </p> <p> <strong>Conditions –</strong> </p> <ol style="list-style-type: lower-roman;"> <li>If the first element is a symbol and the last a number, the codes for these two (the first and the last elements) are to be interchanged.</li> <li>If the first element is an odd number and the last an even number, the first and last elements are to be coded as ©</li> <li>If both second and third elements are perfect squares, the third element is to be coded as the code for the second element.</li> </ol> <p> What will be the code for the following group?<br/>7 4 9 @ $ </p>`,
